import{_ as h,C as n,o as l,c as d,j as t,a as s,E as o,a2 as a}from"./chunks/framework.sc8Z_ZE3.js";const F=JSON.parse('{"title":"First run","description":"","frontmatter":{},"headers":[],"relativePath":"start/first-run.md","filePath":"start/first-run.md"}'),p={name:"start/first-run.md"};function c(u,e,k,g,m,y){const r=n("Badge"),i=n("Shot");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"first-run",tabindex:"-1"},[s("First run "),t("a",{class:"header-anchor",href:"#first-run","aria-label":'Permalink to "First run"'},"​")],-1)),o(r,{type:"built",text:"Built"}),e[1]||(e[1]=a(`<p>Octryx AI is the layer above your coding agent: you bring Claude Code (Codex support is experimental), Octryx AI brings the process, the checks and the record. This walkthrough starts Octryx AI on your machine with a small local demo and runs one real workflow on it.</p><p><strong>A local demo, not for production.</strong> Everything listens on <code>127.0.0.1</code> only.</p><div class="info custom-block"><p class="custom-block-title">What has been checked</p><p>Steps 1 to 5 were checked on a fresh clone of this repository. Steps 6 to 9 were walked through twice on a fresh compose demo by someone following this page, the second time on the current version. Both times the Claude subscription was already logged in: <code>octryx-claude login --seat</code> itself was not run in those tests. It is Claude Code&#39;s own subscription login and needs your browser.</p></div><h2 id="you-need" tabindex="-1">You need <a class="header-anchor" href="#you-need" aria-label="Permalink to &quot;You need&quot;">​</a></h2><ul><li>Docker Desktop, Rancher Desktop or Podman with <code>docker compose</code> 2.23 or newer (<code>docker compose version</code>). Give the container engine 8 GB of memory and 20 GB of disk.</li><li>Access to one model: an Anthropic API key, an OpenAI-compatible endpoint with a key, or AWS Bedrock.</li><li>Chrome, Edge or Firefox.</li><li>For the run in step 6: <a href="https://claude.ai/code" target="_blank" rel="noreferrer">Claude Code</a> with a Claude subscription (Pro or Max), signed in, and <code>git</code>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What you will see <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What you will see&quot;">​</a></h2><ul><li>a Workspace <strong>Demo Shop</strong> with a small sample shop on a local stand-in for GitHub, its docs as Knowledge, a PR review bot and two work items;</li><li>the demo bug <strong>OCX-1</strong> &quot;Order total takes the discount as an amount&quot;;</li><li>Octryx AI starting the bug workflow on your machine: your Claude Code reproduces the bug with a failing test and fixes it, and the platform checks the test red before and green after;</li><li>a pull request on the local GitHub, and the run&#39;s record: phases, evidence, tokens and cost;</li><li>the review bot&#39;s comments on that pull request.</li></ul><p>The first build of the images takes 10 to 20 minutes, once. On our development stack, with the images built, one cold run took <strong>2:57 min from the stack&#39;s start to the review bot&#39;s comment</strong>: from <strong>Start</strong> to the pull request 69 s, the bot&#39;s review 23 s later. See <a href="/docs/start/status#time-to-the-first-pull-request">Status and results</a>.</p><h2 id="_1-get-the-code-and-choose-a-model" tabindex="-1">1. Get the code and choose a model <a class="header-anchor" href="#_1-get-the-code-and-choose-a-model" aria-label="Permalink to &quot;1. Get the code and choose a model&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/octryx-ai/octryx.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> octryx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Fill in <strong>one</strong> model block in <code>.env</code>, for example Anthropic:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AGENT_DEFAULT_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-sonnet-5-5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Nothing else goes into <code>.env</code>: the database password, the signing and encryption keys and the object store credentials are generated on the first start and stay in Docker volumes.</p><p>The model settings are read only on the first start; after that you change models under <strong>Admin › Models</strong>. To start over with another block in <code>.env</code>, remove the install first with <code>down -v</code> (see <a href="#stop-or-start-over">Stop or start over</a>), which deletes its data.</p><h2 id="_2-start-octryx-ai-with-the-demo" tabindex="-1">2. Start Octryx AI with the demo <a class="header-anchor" href="#_2-start-octryx-ai-with-the-demo" aria-label="Permalink to &quot;2. Start Octryx AI with the demo&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><p>The first build takes 10 to 20 minutes. The demo is ready when its log shows <code>demo: ready in the Workspace &#39;Demo Shop&#39;</code>, followed by its address. Port 8000 or 8434 taken? Set <code>OCTRYX_PORT</code> and <code>OCTRYX_DEMO_GIT_PORT</code> in <code>.env</code> first.</p><h2 id="_3-create-your-administrator" tabindex="-1">3. Create your administrator <a class="header-anchor" href="#_3-create-your-administrator" aria-label="Permalink to &quot;3. Create your administrator&quot;">​</a></h2><p>There is no default password. The first start prints a one-time setup code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;setup code&quot;</span></span></code></pre></div><p>Open <code>http://localhost:8000/chat/setup</code> and enter the code, your name, e-mail and a password of at least 12 characters. From then on you sign in as <strong>admin</strong> with that password.</p>`,21)),o(i,{src:"/shots/first-run/setup.jpg",alt:"The first-start page: a notice 'Local demo, not for production', then the fields setup code, name, e-mail and password and the button Create administrator",caption:"First start: the setup code from the log creates the administrator."}),e[2]||(e[2]=a('<h2 id="_4-open-the-demo-shop" tabindex="-1">4. Open the Demo Shop <a class="header-anchor" href="#_4-open-the-demo-shop" aria-label="Permalink to &quot;4. Open the Demo Shop&quot;">​</a></h2><p>Choose the Workspace with the top icon in the left bar, then <strong>Demo Shop</strong>. Then <strong>Work</strong> in the left bar: it opens on <strong>Runs</strong>. Choose <strong>Work items</strong>: it opens on <strong>My work</strong>, which is empty because nothing is assigned to you yet. Its button <strong>Show all items</strong> (or the tab <strong>All items</strong>) lists OCX-1 and OCX-2.</p>',2)),o(i,{src:"/shots/first-run/work-items.jpg",alt:"Work › Work items in the Demo Shop with two items in Intake: OCX-2 Free shipping from 50.00 and OCX-1 Order total takes the discount as an amount",caption:"The demo's two work items: a bug and a small story."}),e[3]||(e[3]=t("h2",{id:"_5-search-the-knowledge",tabindex:"-1"},[s("5. Search the Knowledge "),t("a",{class:"header-anchor",href:"#_5-search-the-knowledge","aria-label":'Permalink to "5. Search the Knowledge"'},"​")],-1)),e[4]||(e[4]=t("p",null,[t("strong",null,"Knowledge › Search"),s(` for "rollback" finds the Demo Shop's incident runbook, with the passage, its source file and section.`)],-1)),o(i,{src:"/shots/first-run/knowledge-rollback.jpg",alt:"Knowledge › Search for rollback: one source passage from docs/incident-runbook.md in the Demo Shop",caption:"Knowledge: every passage keeps its source."}),e[5]||(e[5]=t("h3",{id:"without-claude-code-see-a-finished-run",tabindex:"-1"},[s("Without Claude Code: see a finished run "),t("a",{class:"header-anchor",href:"#without-claude-code-see-a-finished-run","aria-label":'Permalink to "Without Claude Code: see a finished run"'},"​")],-1)),e[6]||(e[6]=t("p",null,[t("strong",null,"Work › Runs"),s(" shows a run with the badge "),t("strong",null,"Sample run"),s(": a real "),t("strong",null,"Story / epic delivery"),s(" run of OCX-2, recorded on another install, with its phases, its pull request and the bot's review on the local GitHub. The bot asks for changes there: the new tests lock in the discount bug of OCX-1, which is still open.")],-1)),o(i,{src:"/shots/first-run/sample-run-card.png",alt:"The sample run's card: Epic delivery, Phase 1/1, Completed, badge Sample run; OCX-2 Free shipping from 50.00, the step Implement the story on the branch feature/OCX-2-free-shipping-from-50-00, Checks passed, and the timeline How this run went from Run: started to Run finished: done",caption:"The run card of the sample run (Story / epic delivery on OCX-2)."}),e[7]||(e[7]=t("p",null,[s("Its pull request and the bot's review are on the local GitHub at "),t("code",null,"http://127.0.0.1:8434/demo/demo-shop/pull/1"),s(". That page is the demo's own read-only stand-in for GitHub, so formatting shows as plain text there.")],-1)),o(i,{src:"/shots/first-run/sample-run-pr.png",alt:"Pull request OCX-2: Free shipping from 50.00 #1, Open, from feature/OCX-2-free-shipping-from-50-00 into main in demo/demo-shop; files changed shop/pricing.py and tests/test_pricing.py, 2 files changed, 44 insertions, 1 deletion",caption:"The sample run's pull request on the demo's local GitHub."}),o(i,{src:"/shots/first-run/sample-run-review.png",alt:"The review bot's review with two inline findings in tests/test_pricing.py: F1 Medium, the test expects a total that only holds because of the open OCX-1 discount bug; F2 Low, add a boundary test at 49.99 and 50.00; below it the check octryx/review success, Informational: 1 medium, 1 low",caption:"The review bot's findings on it. Status inform reports and never blocks."}),e[8]||(e[8]=a(`<h2 id="_6-connect-your-machine" tabindex="-1">6. Connect your machine <a class="header-anchor" href="#_6-connect-your-machine" aria-label="Permalink to &quot;6. Connect your machine&quot;">​</a></h2><p>Workflows that only read or write text run on the Octryx AI server with the model from <code>.env</code>. A run that changes and tests code runs on your machine, with your Claude Code paired through the launcher: Octryx AI does not build or test code on its server. So without a paired machine, <strong>Bug fix with a reproduction test</strong> and <strong>Story / epic delivery</strong> do not start: the Start workflow form says so and how to pair Claude Code, and a refused start ends with &quot;No device yet: pair Claude Code with the launcher (Agents › Install octryx-claude).&quot; <strong>Spec writing</strong> is allowed on the server, but it is made for an epic (it interviews you, writes a specification for your approval and splits it into stories), not for a small item like OCX-1 or OCX-2. Where an admin has turned on <strong>Jira intake &amp; triage</strong> and the triage hands over to such a workflow, the run card shows <strong>Follow-up not started</strong> with the reason and the link <strong>Pair Claude Code with the launcher</strong>.</p><p>In Octryx AI, choose <strong>Agents</strong> (an icon in the left bar), then <strong>Clients › Install octryx-claude</strong>. It shows the install line for your Workspace; run it in a terminal. The installer opens the browser to sign in: choose <strong>Authorize</strong>, and the terminal says &quot;Logged in … Workspace: Demo Shop&quot;. Then, once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">octryx-claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seat</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # your Claude subscription, for runs on your machine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8434/demo/demo-shop.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/octryx-demo/demo-shop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">octryx-claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --folder</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/octryx-demo/demo-shop</span></span></code></pre></div><p>A run works in a clone of its repository: the device folder is that clone. <code>octryx-claude device status</code> says <code>connected</code>. The device takes your machine&#39;s name.</p><p>Do not skip <code>login --seat</code>. Without it <code>device status</code> says &quot;seat: no login recorded by this launcher&quot;, and the device offers only the <strong>governed</strong> profile, which runs on a Claude model of the platform itself and does not use your subscription. This walkthrough uses the seat.</p><h2 id="_7-start-the-run" tabindex="-1">7. Start the run <a class="header-anchor" href="#_7-start-the-run" aria-label="Permalink to &quot;7. Start the run&quot;">​</a></h2><p>In <strong>Work › Work items › All items</strong>, open <strong>OCX-1</strong> and choose <strong>Start workflow</strong>. Nothing is preselected (<strong>Choose a workflow</strong>): as <strong>Workflow</strong> choose <strong>Bug fix with a reproduction test</strong>, under <strong>Run on</strong> your machine (<code>&lt;machine name&gt; · demo-shop · seat</code>), leave <strong>Model</strong> on <strong>Automatic</strong>, then <strong>Start run</strong>. You can also write &quot;Fix OCX-1&quot; in the chat and pick that workflow.</p>`,8)),o(i,{src:"/shots/first-run/start-workflow.jpg",alt:"OCX-1 with the Start workflow form open: Workflow, Run on, Model and the button Start run, below it the bug's request text",caption:"Start workflow on OCX-1: choose the workflow and where it runs."}),e[9]||(e[9]=a(`<h2 id="_8-watch-it" tabindex="-1">8. Watch it <a class="header-anchor" href="#_8-watch-it" aria-label="Permalink to &quot;8. Watch it&quot;">​</a></h2><p>In <strong>Work › Runs</strong> the run goes through its phases. OCX-1 is an ordinary bug, size class <strong>S</strong> (see <a href="/docs/concepts/workflows#size-classes">Size classes</a>), so reproduction and fix happen in one step:</p><ol><li>Prepare the working folder</li><li>Minimal fix, starting with a test that fails because of the bug</li><li>The CI pipeline: the declared tests, run without the agent, including the proof that the new test fails on the old code</li><li>The independent review</li><li>Push and pull request</li></ol><p>The separate reproduce phase and the browser test are skipped for this class; the run records each skipped step with its reason. On a fresh demo the pull request came about 6 minutes after <strong>Start</strong>.</p><p>The run card says what the run proved and what it cost, and links the pull request. The local GitHub also lists it at <code>http://127.0.0.1:8434/_fake/pulls</code>. After the pull request the run waits for the merge, and in the demo it stays there: the local stand-in for GitHub cannot merge.</p><h2 id="_9-see-the-review-bot" tabindex="-1">9. See the review bot <a class="header-anchor" href="#_9-see-the-review-bot" aria-label="Permalink to &quot;9. See the review bot&quot;">​</a></h2><p>The demo switches the review bot on for <code>demo/demo-shop</code> (status <strong>inform</strong>). A pull request that a run opens is picked up within seconds. The bot posts its review on the local GitHub: a summary with the work item&#39;s acceptance criteria as a table (each criterion, whether the change covers it, and the evidence), and inline findings with a severity, file and line. For OCX-1 the criterion comes from the bug&#39;s expected total, 45.00. The commit status <code>octryx/review</code> is green, with any findings counted, for example &quot;No blocking findings&quot; or &quot;No blocking findings · 1 low&quot;: status <strong>inform</strong> reports and never blocks.</p><p>Reply in the thread with <code>@octryx explain</code>, <code>@octryx pause</code>, <code>@octryx resume</code> or <code>@octryx ignore &lt;reason&gt;</code>. Push a fix and the bot reviews only what changed: the finding is marked fixed and its thread is resolved.</p><h2 id="stop-or-start-over" tabindex="-1">Stop or start over <a class="header-anchor" href="#stop-or-start-over" aria-label="Permalink to &quot;Stop or start over&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.demo.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # delete everything: database, documents, generated keys</span></span></code></pre></div><p>To back up and restore an install (database, generated keys, documents), see <a href="/docs/install/upgrade#back-up-and-restore">Back up and restore</a>.</p><p>To unpair your machine: <code>octryx-claude device disable</code> (your login stays). To remove the launcher: <code>curl -fsSL &#39;http://localhost:8000/octryx-claude/install.sh&#39; | bash -s -- uninstall</code>. See <a href="/docs/install/launcher">Launcher and devices</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><strong>OCX-2</strong> &quot;Free shipping from 50.00&quot;: a story. The sample run already delivered it; a new <strong>Story / epic delivery</strong> on OCX-2 continues on that run&#39;s branch and pull request.</li><li>Your own repository: <strong>Work › Repositories › Add a repository for runs</strong>. See <a href="/docs/work/git">Git repositories and pull requests</a>.</li><li>An install without the demo: <a href="/docs/install/docker">Docker Compose</a>.</li></ul>`,14))])}const w=h(p,[["render",c]]);export{F as __pageData,w as default};
